// identNilCompare returns the identifier compared against nil when be is a
// plain `ident <op> nil` (or `nil <op> ident`) comparison.
func identNilCompare(be *ast.BinaryExpr, op token.Token) (string, bool) {
	if be.Op != op {
		return "", false
	}
	other := ast.Expr(nil)
	if isNilIdent(be.Y) {
		other = be.X
	} else if isNilIdent(be.X) {
		other = be.Y
	} else {
		return "", false
	}
	id, ok := stripParens(other).(*ast.Ident)
	if !ok || id.Name == "_" || id.Name == "nil" {
		return "", false
	}
	return id.Name, true
}

// closureTaintedNames collects names that can change behind the scanner's
// back at any point: names assigned inside a function literal (the closure
// may run between a fact and a later check) and names whose address is taken
// anywhere in the body. Facts are never established for them.
func closureTaintedNames(body *ast.BlockStmt) map[string]bool {
	t := map[string]bool{}
	ast.Inspect(body, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.UnaryExpr:
			if v.Op == token.AND {
				if id, ok := stripParens(v.X).(*ast.Ident); ok {
					t[id.Name] = true
				}
			}
		case *ast.FuncLit:
			ast.Inspect(v.Body, func(m ast.Node) bool {
				switch w := m.(type) {
				case *ast.AssignStmt:
					for _, lhs := range w.Lhs {
						if id, ok := lhs.(*ast.Ident); ok {
							t[id.Name] = true
						}
					}
				case *ast.IncDecStmt:
					if id, ok := w.X.(*ast.Ident); ok {
						t[id.Name] = true
					}
				}
				return true
			})
		}
		return true
	})
	return t
}

func (s *nilCheckScanner) walkStmt(stmt ast.Stmt, vars map[string]nilVarState) {
	switch st := stmt.(type) {
	case *ast.AssignStmt:
		s.checkExprs(st.Rhs, vars)
		invalidateNilFacts(st, vars)
		s.recordNilAssign(st, vars)
	case *ast.DeclStmt:
		invalidateNilFacts(st, vars)
		s.recordNilDecl(st, vars)
	case *ast.IfStmt:
		s.walkIf(st, vars)
	case *ast.BlockStmt:
		s.walkStmts(st.List, copyNilVars(vars))
		invalidateNilFacts(st, vars)
	case *ast.ForStmt:
		inner := copyNilVars(vars)
		if st.Init != nil {
			s.walkStmt(st.Init, inner)
		}
		s.walkStmts(st.Body.List, stripNilFacts(inner))
		invalidateNilFacts(st, vars)
	case *ast.RangeStmt:
		s.checkExpr(st.X, vars)
		inner := copyNilVars(vars)
		if st.Tok == token.DEFINE {
			for _, e := range []ast.Expr{st.Key, st.Value} {
				if id, ok := e.(*ast.Ident); ok && id.Name != "_" {
					inner[id.Name] = nilVarState{local: true}
				}
			}
		}
		s.walkStmts(st.Body.List, stripNilFacts(inner))
		invalidateNilFacts(st, vars)
	case *ast.SwitchStmt:
		s.walkSwitch(st, vars)
	case *ast.TypeSwitchStmt:
		scope := copyNilVars(vars)
		if st.Init != nil {
			s.walkStmt(st.Init, scope)
		}
		invalidateNilFacts(st.Assign, scope)
		for _, c := range st.Body.List {
			if cc, ok := c.(*ast.CaseClause); ok {
				s.walkStmts(cc.Body, copyNilVars(scope))
			}
		}
		invalidateNilFacts(st, vars)
	case *ast.SelectStmt:
		for _, c := range st.Body.List {
			if cc, ok := c.(*ast.CommClause); ok {
				scope := copyNilVars(vars)
				if cc.Comm != nil {
					s.walkStmt(cc.Comm, scope)
				}
				s.walkStmts(cc.Body, scope)
			}
		}
		invalidateNilFacts(st, vars)
	case *ast.ReturnStmt:
		s.checkExprs(st.Results, vars)
		invalidateNilFacts(st, vars)
	case *ast.ExprStmt:
		s.checkExpr(st.X, vars)
		invalidateNilFacts(st, vars)
	default:
		invalidateNilFacts(stmt, vars)
	}
}

func (s *nilCheckScanner) walkSwitch(st *ast.SwitchStmt, vars map[string]nilVarState) {
	scope := copyNilVars(vars)
	if st.Init != nil {
		s.walkStmt(st.Init, scope)
	}
	if st.Tag != nil {
		s.checkExpr(st.Tag, scope)
	}
	fall := false
	ast.Inspect(st.Body, func(n ast.Node) bool {
		if b, ok := n.(*ast.BranchStmt); ok && b.Tok == token.FALLTHROUGH {
			fall = true
		}
		return !fall
	})
	for _, c := range st.Body.List {
		cc, ok := c.(*ast.CaseClause)
		if !ok {
			continue
		}
		if st.Tag == nil {
			s.checkExprs(cc.List, scope)
		}
		body := copyNilVars(scope)
		if fall {
			// A fallthrough lets one case's assignments reach the next
			// case's checks; drop flow facts for every body.
			body = stripNilFacts(body)
		}
		s.walkStmts(cc.Body, body)
	}
	invalidateNilFacts(st, vars)
}

func (s *nilCheckScanner) walkIf(st *ast.IfStmt, vars map[string]nilVarState) {
	scope := vars
	if st.Init != nil {
		scope = copyNilVars(vars)
		s.walkStmt(st.Init, scope)
	}
	s.checkExpr(st.Cond, scope)
	invalidateNilFacts(st.Cond, scope)

	bodyVars := copyNilVars(scope)
	s.establishFacts(bodyVars, nonNilConjunctNames(st.Cond), factGuarded, s.line(st.Cond))
	s.walkStmts(st.Body.List, bodyVars)

	if st.Else != nil {
		elseVars := copyNilVars(scope)
		// In the else branch the condition is false, so every `x == nil`
		// disjunct is false: those names are non-nil.
		s.establishFacts(elseVars, nilEqDisjunctNames(st.Cond, false), factGuarded, s.line(st.Cond))
		s.walkStmt(st.Else, elseVars)
	}

	invalidateNilFacts(st, vars)

	// Fall-through past `if x == nil { return }` (no else, terminal body)
	// proves x non-nil for the rest of this statement list. Skipped when the
	// if declares its own variables — the guard may cover a shadowed x.
	if st.Else == nil && st.Init == nil && terminatesFlow(st.Body) {
		s.establishFacts(vars, nilEqDisjunctNames(st.Cond, false), factRejected, s.line(st.Cond))
	}
}

func terminatesFlow(body *ast.BlockStmt) bool {
	if body == nil || len(body.List) == 0 {
		return false
	}
	switch last := body.List[len(body.List)-1].(type) {
	case *ast.ReturnStmt:
		return true
	case *ast.BranchStmt:
		return last.Tok == token.BREAK || last.Tok == token.CONTINUE
	case *ast.ExprStmt:
		call, ok := last.X.(*ast.CallExpr)
		if !ok {
			return false
		}
		switch fun := call.Fun.(type) {
		case *ast.Ident:
			return fun.Name == "panic"
		case *ast.SelectorExpr:
			if x, ok := fun.X.(*ast.Ident); ok {
				return (x.Name == "os" && fun.Sel.Name == "Exit") ||
					(x.Name == "log" && strings.HasPrefix(fun.Sel.Name, "Fatal"))
			}
		}
	}
	return false
}

// invalidateNilFacts drops flow facts for every name node could have changed:
// assignment/inc-dec targets, redeclarations (which also shadow, so the kind
// is cleared), range variables, and receivers of method calls when the
// receiver kind could let the method mutate the variable itself (a named
// slice/map — or unknown — can have pointer-receiver methods that assign
// through the implicit &x; a *T or interface receiver cannot rebind x).
func invalidateNilFacts(node ast.Node, vars map[string]nilVarState) {
	if node == nil {
		return
	}
	clear := func(name string, shadow bool) {
		v, ok := vars[name]
		if !ok {
			return
		}
		v.fact = factNone
		if shadow {
			v.kind = ""
		}
		vars[name] = v
	}
	ast.Inspect(node, func(n ast.Node) bool {
		switch st := n.(type) {
		case *ast.AssignStmt:
			for _, lhs := range st.Lhs {
				if id, ok := lhs.(*ast.Ident); ok {
					clear(id.Name, st.Tok == token.DEFINE)
				}
			}
		case *ast.IncDecStmt:
			if id, ok := st.X.(*ast.Ident); ok {
				clear(id.Name, false)
			}
		case *ast.ValueSpec:
			for _, id := range st.Names {
				clear(id.Name, true)
			}
		case *ast.RangeStmt:
			for _, e := range []ast.Expr{st.Key, st.Value} {
				if id, ok := e.(*ast.Ident); ok {
					clear(id.Name, st.Tok == token.DEFINE)
				}
			}
		case *ast.UnaryExpr:
			if st.Op == token.AND {
				if id, ok := stripParens(st.X).(*ast.Ident); ok {
					clear(id.Name, false)
				}
			}
		case *ast.CallExpr:
			if sel, ok := st.Fun.(*ast.SelectorExpr); ok {
				if id, ok := stripParens(sel.X).(*ast.Ident); ok {
					if k := vars[id.Name].kind; k != kindPointer && k != kindIface {
						clear(id.Name, false)
					}
				}
			}
		}
		return true
	})
}

func (s *nilCheckScanner) recordNilAssign(st *ast.AssignStmt, vars map[string]nilVarState) {
	pairwise := len(st.Lhs) == len(st.Rhs)
	for i, lhs := range st.Lhs {
		id, ok := lhs.(*ast.Ident)
		if !ok || id.Name == "_" {
			continue
		}
		prev := vars[id.Name]
		state := nilVarState{local: prev.local || st.Tok == token.DEFINE}
		if st.Tok == token.ASSIGN {
			state.kind = prev.kind // plain assignment cannot change the type
		}
		if pairwise {
			kind, nonNil := constructedNonNil(st.Rhs[i])
			if kind != "" {
				state.kind = kind
			}
			if nonNil && state.local && !s.tainted[id.Name] {
				state.fact = factConstructed
				state.factLine = s.line(st)
			}
		}
		vars[id.Name] = state
	}
}

func (s *nilCheckScanner) recordNilDecl(st *ast.DeclStmt, vars map[string]nilVarState) {
	gen, ok := st.Decl.(*ast.GenDecl)
	if !ok || gen.Tok != token.VAR {
		return
	}
	for _, spec := range gen.Specs {
		vs, ok := spec.(*ast.ValueSpec)
		if !ok {
			continue
		}
		var declaredKind string
		if vs.Type != nil {
			declaredKind = nilCheckTypeKind(vs.Type)
		}
		for i, id := range vs.Names {
			if id == nil || id.Name == "_" {
				continue
			}
			state := nilVarState{local: true, kind: declaredKind}
			if vs.Type == nil && len(vs.Values) == len(vs.Names) {
				kind, nonNil := constructedNonNil(vs.Values[i])
				state.kind = kind
				if nonNil && !s.tainted[id.Name] {
					state.fact = factConstructed
					state.factLine = s.line(st)
				}
			}
			vars[id.Name] = state
		}
	}
}

// constructedNonNil reports whether expr syntactically constructs a value
// that cannot be nil, and the nilable kind it constructs (if recognizable).
func constructedNonNil(expr ast.Expr) (kind string, nonNil bool) {
	switch e := stripParens(expr).(type) {
	case *ast.UnaryExpr:
		if e.Op == token.AND {
			return kindPointer, true
		}
	case *ast.CallExpr:
		id, ok := e.Fun.(*ast.Ident)
		if !ok {
			return "", false
		}
		switch id.Name {
		case "new":
			return kindPointer, true
		case "make":
			if len(e.Args) > 0 {
				return nilCheckTypeKind(e.Args[0]), true
			}
		}
	case *ast.CompositeLit:
		switch t := e.Type.(type) {
		case *ast.ArrayType:
			if t.Len == nil {
				return kindSlice, true
			}
		case *ast.MapType:
			return kindMap, true
		}
	}
	return "", false
}

func (s *nilCheckScanner) checkNilCompare(be *ast.BinaryExpr, vars map[string]nilVarState) {
	if s.consumed[be] {
		return
	}
	name, ok := identNilCompare(be, be.Op)
	if !ok {
		return
	}
	v := vars[name]
	if v.fact == factNone || s.tainted[name] {
		return
	}
	s.consumed[be] = true
	verdict := "can never be true"
	if be.Op == token.NEQ {
		verdict = "is always true"
	}
	var reason string
	switch v.fact {
	case factConstructed:
		reason = fmt.Sprintf("%s was assigned a non-nil value at line %d", name, v.factLine)
	case factGuarded:
		reason = fmt.Sprintf("the branch condition at line %d already establishes %s != nil", v.factLine, name)
	case factRejected:
		reason = fmt.Sprintf("the guard at line %d already returned on nil", v.factLine)
	}
	op := "=="
	if be.Op == token.NEQ {
		op = "!="
	}
	s.issues = append(s.issues, lintIssue{
		File:     s.file,
		Rule:     "unnecessary-nil-check",
		Severity: "warning",
		Message: fmt.Sprintf("func %s: `%s %s nil` (line %d) %s — %s; drop the redundant check",
			s.fn, name, op, s.line(be), verdict, reason),
	})
}

// checkLenCombo flags `x != nil && len(x) > 0` (and `x == nil || len(x) == 0`)
// for slice/map-typed x: len of a nil slice or map is 0, so the len test alone
// is equivalent. The nil-compare node is marked consumed so the fact-based
// check does not double-report the same site.
func (s *nilCheckScanner) checkLenCombo(be *ast.BinaryExpr, vars map[string]nilVarState) {
	compareOp, lenSuffices := token.NEQ, "> 0"
	lenMatches := lenComparePositive
	if be.Op == token.LOR {
		compareOp, lenSuffices = token.EQL, "== 0"
		lenMatches = lenCompareZero
	}
	terms := flattenBool(be, be.Op)
	for _, t := range terms {
		cmp, ok := stripParens(t).(*ast.BinaryExpr)
		if !ok || s.consumed[cmp] {
			continue
		}
		name, ok := identNilCompare(cmp, compareOp)
		if !ok {
			continue
		}
		if k := vars[name].kind; k != kindSlice && k != kindMap {
			continue
		}
		for _, other := range terms {
			if other == t || !lenMatches(other, name) {
				continue
			}
			s.consumed[cmp] = true
			op := "!="
			if compareOp == token.EQL {
				op = "=="
			}
			s.issues = append(s.issues, lintIssue{
				File:     s.file,
				Rule:     "unnecessary-nil-check",
				Severity: "warning",
				Message: fmt.Sprintf("func %s: `%s %s nil` (line %d) is redundant — len(nil) == 0, so `len(%s) %s` alone suffices",
					s.fn, name, op, s.line(cmp), name, lenSuffices),
			})
			break
		}
	}
}

// lenCompareParts normalizes a comparison between len(name) and an integer
// literal to the len-on-the-left orientation, returning the operator and the
// literal value.
func lenCompareParts(e ast.Expr, name string) (token.Token, int, bool) {
	be, ok := stripParens(e).(*ast.BinaryExpr)
	if !ok {
		return 0, 0, false
	}
	op := be.Op
	lhs, rhs := stripParens(be.X), stripParens(be.Y)
	if !isLenOf(lhs, name) {
		lhs, rhs = rhs, lhs
		switch op {
		case token.GTR:
			op = token.LSS
		case token.LSS:
			op = token.GTR
		case token.GEQ:
			op = token.LEQ
		case token.LEQ:
			op = token.GEQ
		}
	}
	if !isLenOf(lhs, name) {
		return 0, 0, false
	}
	lit, ok := rhs.(*ast.BasicLit)
	if !ok || lit.Kind != token.INT {
		return 0, 0, false
	}
	switch lit.Value {
	case "0":
		return op, 0, true
	case "1":
		return op, 1, true
	}
	return 0, 0, false
}

// nilEqDisjunctNames collects the names x with an `x == nil` disjunct at the
// top level of cond. With strict set, every disjunct must be such a compare
// or nothing is returned; loose callers rely only on "cond false ⇒ every
// disjunct false", which tolerates mixed conditions like
// `err != nil || x == nil`.
func nilEqDisjunctNames(cond ast.Expr, strict bool) []string {
	var names []string
	for _, d := range flattenBool(cond, token.LOR) {
		if be, ok := stripParens(d).(*ast.BinaryExpr); ok {
			if name, ok := identNilCompare(be, token.EQL); ok {
				names = append(names, name)
				continue
			}
		}
		if strict {
			return nil
		}
	}
	return names
}

func unnecessaryNilCheckFunc(file string, fset *token.FileSet, fd *ast.FuncDecl) []lintIssue {
	if hasGotoOrLabel(fd.Body) {
		return nil
	}
	s := &nilCheckScanner{
		file:     file,
		fset:     fset,
		fn:       fd.Name.Name,
		tainted:  closureTaintedNames(fd.Body),
		consumed: map[ast.Expr]bool{},
	}
	vars := map[string]nilVarState{}
	addNilCheckParams(vars, fd.Recv)
	addNilCheckParams(vars, fd.Type.Params)
	addNilCheckParams(vars, fd.Type.Results)
	s.walkStmts(fd.Body.List, vars)
	return s.issues
}

func (s *nilCheckScanner) checkExpr(e ast.Expr, vars map[string]nilVarState) {
	if e == nil {
		return
	}
	ast.Inspect(e, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch be.Op {
		case token.LAND, token.LOR:
			s.checkLenCombo(be, vars)
		case token.EQL, token.NEQ:
			s.checkNilCompare(be, vars)
		}
		return true
	})
}

// hasEntryNilGuard reports whether fd nil-checks param in its entry prologue.
// The prologue may hold several guards in sequence — each an `x == nil`-shaped
// reject (a single compare or an `||` chain of them) whose body immediately
// returns — interleaved with simple assign/decl/expr statements. Scanning
// continues past guards for other parameters, so every guard in the prologue
// is recognized, not just the first.
func hasEntryNilGuard(fd *ast.FuncDecl, param string) bool {
	if fd.Body == nil || len(fd.Body.List) == 0 {
		return false
	}
	for _, stmt := range fd.Body.List {
		switch s := stmt.(type) {
		case *ast.AssignStmt, *ast.DeclStmt, *ast.ExprStmt:
			continue
		case *ast.IfStmt:
			if !bodyStartsWithReturn(s.Body) {
				return false
			}
			names := nilRejectGuardNames(s.Cond)
			if len(names) == 0 {
				return false
			}
			if slices.Contains(names, param) {
				return true
			}
			continue // a nil guard for other params — still function entry
		default:
			return false
		}
	}
	return false
}

// nonNilConjunctNames returns the names x for which cond being true
// establishes x != nil: the top-level `&&` conjuncts of cond that are plain
// `x != nil` compares. Other conjuncts are allowed — a true conjunction makes
// every conjunct true.
func nonNilConjunctNames(cond ast.Expr) []string {
	var names []string
	for _, c := range flattenBool(cond, token.LAND) {
		if be, ok := stripParens(c).(*ast.BinaryExpr); ok {
			if name, ok := identNilCompare(be, token.NEQ); ok {
				names = append(names, name)
			}
		}
	}
	return names
}

func hasGotoOrLabel(body *ast.BlockStmt) bool {
	found := false
	ast.Inspect(body, func(n ast.Node) bool {
		switch b := n.(type) {
		case *ast.LabeledStmt:
			found = true
		case *ast.BranchStmt:
			if b.Tok == token.GOTO {
				found = true
			}
		}
		return !found
	})
	return found
}

func addNilCheckParams(vars map[string]nilVarState, fl *ast.FieldList) {
	if fl == nil {
		return
	}
	for _, f := range fl.List {
		kind := nilCheckTypeKind(f.Type)
		for _, n := range f.Names {
			if n == nil || n.Name == "" || n.Name == "_" {
				continue
			}
			vars[n.Name] = nilVarState{local: true, kind: kind}
		}
	}
}

func nilCheckTypeKind(typ ast.Expr) string {
	switch t := typ.(type) {
	case *ast.ArrayType:
		if t.Len == nil {
			return kindSlice
		}
		return ""
	case *ast.MapType:
		return kindMap
	}
	return nilableKind(typ) // "pointer", "interface", or ""
}

func isLenOf(e ast.Expr, name string) bool {
	call, ok := e.(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return false
	}
	fun, ok := call.Fun.(*ast.Ident)
	if !ok || fun.Name != "len" {
		return false
	}
	id, ok := stripParens(call.Args[0]).(*ast.Ident)
	return ok && id.Name == name
}

func (s *nilCheckScanner) establishFacts(vars map[string]nilVarState, names []string, fact nilFactKind, line int) {
	for _, name := range names {
		v, ok := vars[name]
		if !ok || !v.local || s.tainted[name] || v.fact != factNone {
			continue
		}
		v.fact = fact
		v.factLine = line
		vars[name] = v
	}
}

func wantIssueCount(t *testing.T, issues []lintIssue, n int) {
	t.Helper()
	if len(issues) != n {
		t.Fatalf("issues = %+v, want %d", issues, n)
	}
	for _, iss := range issues {
		if iss.Rule != "unnecessary-nil-check" {
			t.Fatalf("rule = %q", iss.Rule)
		}
	}
}

type nilCheckScanner struct {
	file    string
	fset    *token.FileSet
	fn      string
	tainted map[string]bool
	// consumed marks nil-compare nodes already reported (or folded into a
	// len-combo report) so one site never yields two findings.
	consumed map[ast.Expr]bool
	issues   []lintIssue
}

// nilRejectGuardNames returns the names x for which cond is an `x == nil`
// test, treating a top-level `||` chain as one combined guard: falling past
// `if a == nil || b == nil { return }` proves both a and b non-nil. Any
// disjunct that is not a plain `ident == nil` compare disqualifies the whole
// condition — a mixed guard does more than nil-check, so "drop the guard" is
// not safe advice for it.
func nilRejectGuardNames(cond ast.Expr) []string {
	return nilEqDisjunctNames(cond, true)
}

// nilVarState is the per-scope knowledge about one variable. kind is a static
// type property (survives plain assignment, cleared by shadowing); fact is a
// flow fact (cleared by anything that could change the value).
type nilVarState struct {
	local    bool
	kind     string
	fact     nilFactKind
	factLine int
}

// lenComparePositive matches len(name) > 0, len(name) != 0, len(name) >= 1
// (and the mirrored literal-first spellings).
func lenComparePositive(e ast.Expr, name string) bool {
	op, lit, ok := lenCompareParts(e, name)
	if !ok {
		return false
	}
	return (op == token.GTR && lit == 0) || (op == token.NEQ && lit == 0) || (op == token.GEQ && lit == 1)
}

// lenCompareZero matches len(name) == 0, len(name) < 1, len(name) <= 0
// (and the mirrored literal-first spellings).
func lenCompareZero(e ast.Expr, name string) bool {
	op, lit, ok := lenCompareParts(e, name)
	if !ok {
		return false
	}
	return (op == token.EQL && lit == 0) || (op == token.LSS && lit == 1) || (op == token.LEQ && lit == 0)
}

func runUnnecessaryNilCheck(t *testing.T, src string) []lintIssue {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "a.go")
	if err := os.WriteFile(path, []byte(src), 0o644); err != nil {
		t.Fatal(err)
	}
	return unnecessaryNilCheckRule{}.Run(LintContext{Files: []string{path}})
}

// flattenBool splits e into its leaves under the given boolean operator
// (token.LAND or token.LOR), looking through parentheses.
func flattenBool(e ast.Expr, op token.Token) []ast.Expr {
	if be, ok := stripParens(e).(*ast.BinaryExpr); ok && be.Op == op {
		return append(flattenBool(be.X, op), flattenBool(be.Y, op)...)
	}
	return []ast.Expr{e}
}

func stripParens(e ast.Expr) ast.Expr {
	for {
		p, ok := e.(*ast.ParenExpr)
		if !ok {
			return e
		}
		e = p.X
	}
}

func copyNilVars(vars map[string]nilVarState) map[string]nilVarState {
	out := make(map[string]nilVarState, len(vars))
	for k, v := range vars {
		out[k] = v
	}
	return out
}

func stripNilFacts(vars map[string]nilVarState) map[string]nilVarState {
	for k, v := range vars {
		v.fact = factNone
		vars[k] = v
	}
	return vars
}

func (s *nilCheckScanner) walkStmts(list []ast.Stmt, vars map[string]nilVarState) {
	for _, stmt := range list {
		s.walkStmt(stmt, vars)
	}
}

func (s *nilCheckScanner) checkExprs(exprs []ast.Expr, vars map[string]nilVarState) {
	for _, e := range exprs {
		s.checkExpr(e, vars)
	}
}

func enclosingNonNilGuard(body *ast.BlockStmt, call *ast.CallExpr, name string) bool {
	var found bool
	ast.Inspect(body, func(n ast.Node) bool {
		if found || n == nil {
			return false
		}
		ifs, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		if slices.Contains(nonNilConjunctNames(ifs.Cond), name) && nodeContains(ifs.Body, call) {
			found = true
			return false
		}
		return true
	})
	return found
}

func precedingNilReject(body *ast.BlockStmt, call *ast.CallExpr, name string) bool {
	var okProven bool
	var walkBlocks func(list []ast.Stmt)
	walkBlocks = func(list []ast.Stmt) {
		if okProven {
			return
		}
		for i, stmt := range list {
			if nodeContains(stmt, call) {
				for j := 0; j < i; j++ {
					ifs, ok := list[j].(*ast.IfStmt)
					if ok && slices.Contains(nilRejectGuardNames(ifs.Cond), name) && bodyStartsWithReturn(ifs.Body) {
						okProven = true
						return
					}
				}
			}
			ast.Inspect(stmt, func(n ast.Node) bool {
				if b, ok := n.(*ast.BlockStmt); ok && n != stmt {
					walkBlocks(b.List)
					return false
				}
				return !okProven
			})
		}
	}
	walkBlocks(body.List)
	return okProven
}

}
for _, p := range fn.params {
	if !hasEntryNilGuard(fn.decl, p.name) {
		continue
	}

