func TestDocDrift_RuleCountMatches(t *testing.T) {
	doc := readCommandReferenceDoc(t)
	want := len(defaultLintRules())
	re := regexp.MustCompile(`(\d+) (?:default|structural) rules`)
	matches := re.FindAllStringSubmatch(doc, -1)
	if len(matches) == 0 {
		t.Fatal("README.md no longer states a rule count; update this test's pattern")
	}
	for _, m := range matches {
		if m[1] != strconv.Itoa(want) {
			t.Errorf("README.md claims %q but the registry has %d rules; update the doc", m[0], want)
		}
	}
}

// TestDoctorInstall_EnumeratesLiveRegistry pins the installed snippet to the
// live rule registry: every registered rule and every mechanically-fixable
// rule must be named. Deleting the enumeration from the generator's output
// fails this for all 40+ rules at once.
func TestDoctorInstall_EnumeratesLiveRegistry(t *testing.T) {
	dir := t.TempDir()
	t.Chdir(dir)
	if err := doctorInstallCommand([]string{"--target", "claude.md"}); err != nil {
		t.Fatal(err)
	}
	content := readFile(t, "CLAUDE.md")
	for _, r := range defaultLintRules() {
		if !strings.Contains(content, r.Name()) {
			t.Errorf("installed rules do not name registered rule %q", r.Name())
		}
		if _, ok := r.(FixableRule); ok && !strings.Contains(content, r.Name()) {
			t.Errorf("fixable rule %q missing from installed rules", r.Name())
		}
	}
	if want := strconv.Itoa(len(defaultLintRules())); !strings.Contains(content, "("+want+")") {
		t.Errorf("installed rules do not state the live rule count %s", want)
	}
}

// BenchmarkLint measures the in-process lint rule phase over this repo. It excludes the
// subprocess-backed rules (arch-violation, untested-function; golangci-lint is no longer a default
// lint rule — it runs in doctor) so the numbers reflect the AST work being optimized.
func BenchmarkLint(b *testing.B) {
	files, err := analyzer.WalkGoFiles("../..", analyzer.DefaultWalkOptions())
	if err != nil {
		b.Fatal(err)
	}
	skip := map[string]bool{"arch-violation": true, "untested-function": true}

	var rules []LintRule
	for _, r := range defaultLintRules() {
		if !skip[r.Name()] {
			rules = append(rules, r)
		}
	}
	opts := lintOptions{root: "../..", failOn: "error"}
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		ctx := LintContext{Root: "../..", Files: files, MaxSize: 600}
		_ = runLintRules(rules, ctx, opts)
	}
}

